// Capacitive soil moisture: the reading drops as the soil gets wetter.
const int SENSOR_PIN = {{AOUT}};

// Calibrate: read the sensor in dry air and in a glass of water.
const int DRY_READING = 520;
const int WET_READING = 260;

void setup() {
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(SENSOR_PIN);
  int percent = constrain(map(raw, DRY_READING, WET_READING, 0, 100), 0, 100);
  Serial.print("Soil moisture: ");
  Serial.print(percent);
  Serial.print(" % (raw ");
  Serial.print(raw);
  Serial.println(")");
  delay(1000);
}
